INSERT INTO `products` (`id`, `category_id`, `name`, `slug`, `description`, `ingredients`, `nutritional_info`, `weight`, `shelf_life`, `storage_instructions`, `image`, `bg_color`, `price`, `original_price`, `discount_percentage`, `stock`, `sku`, `is_active`, `is_featured`, `is_combo`, `is_new`, `is_vegetarian`, `country_of_origin`, `created_at`, `updated_at`) VALUES
(16, 3, '3x APPLE', '3-pack-apple', 'Three packs of our crisp and sweet dehydrated Kashmiri apples. Light, healthy, and naturally sweet.', '[\"Apple\"]', '{\"Per 100 g\":\"\",\"Energy\":\"250 kcal\",\"Protein\":\"1.5 g\",\"Carbohydrate\":\"67 g\",\"Total Sugars\":\"58 g\",\"Total Fat\":\"0.5 g\",\"Dietary Fiber\":\"8.2 g\",\"Sodium\":\"4 mg\"}', '0.045', '6 months', '0', 'assets/images/products/prod_69d5f52a19242.jpeg', '', 169.00, 360.00, 0, 12, NULL, 1, 1, 0, 0, 1, '0', '2026-01-17 14:47:53', '2026-04-14 06:27:57'),
(17, 3, '3x BANANA', '3-pack-banana', 'Triple the goodness of our soft and chewy dehydrated bananas. No added sugar, just pure fruit energy.', '[\"Banana\"]', '{\"Per 100 g\":\"\",\"Energy\":\"310 kcal\",\"Protein\":\"3.2 g\",\"Carbohydrate\":\"80 g\",\"Total Sugars\":\"43 g\",\"Total Fat\":\"1.0 g\",\"Dietary Fiber\":\"8.3 g\",\"Sodium\":\"4 mg\"}', '0.090', '6 months', '0', 'assets/images/products/prod_69d5f519a485c.jpeg', '', 220.00, 360.00, 0, 12, NULL, 1, 1, 0, 0, 1, '0', '2026-01-17 14:47:53', '2026-04-14 06:27:57'),
(18, 3, 'Fruit Combo', '3-pack-mix', 'Fruit Trio Mix (Apple + Banana + Kiwi) ,taste the full range with one pack each of our Apple Rings, Banana Coins, and Kiwi Slices. The ultimate fruit snack variety.', '[\"Apple\",\"Banana\",\"Kiwi\"]', '{\"Per 100 g (Avg)\":\"\",\"Energy\":\"293 kcal\",\"Protein\":\"2.6 g\",\"Carbohydrate\":\"74 g\",\"Dietary Fiber\":\"10.3 g\",\"Sodium\":\"5 mg\"}', '0.250', '6 months', '0', 'assets/images/products/prod_69d5f4c7c1ec2.jpeg', '', 250.00, 270.00, 0, 23, NULL, 1, 1, 1, 0, 1, '0', '2026-01-17 14:47:53', '2026-04-15 04:28:26'),
(20, 3, 'The Grand Driyum Experience Hamper', 'grand-hamper', 'The complete collection of Driyum\'s finest. Includes Banana, Apple, Kiwi, Alle hachi, and Wangan hachi. A perfect gift for health enthusiasts.', '[\"Banana\",\"Apple\",\"Kiwi\",\"Alle hachi\",\"Wangan hachi\"]', '{\"Variety Pack\":\"Multiple\"}', '0.57', '6 months', '0', 'assets/images/products/prod_69d5f651386ae.jpeg', '#F0FDFA', 849.00, 1150.00, 0, 0, NULL, 0, 0, 0, 0, 1, '0', '2026-01-17 14:47:53', '2026-04-08 06:31:45'),
(21, 1, 'Banana', 'banana', 'Driyum Banana is made from carefully selected ripe bananas, gently dehydrated to lock in their natural sweetness and texture. Soft, chewy, and naturally satisfying—this is banana in its purest, most convenient form. No added sugar, no additives, just real fruit.', '[\"Banana\"]', '{\"Per 100 g\":\"\",\"Energy\":\"310 kcal\",\"Protein\":\"3.2 g\",\"Carbohydrate\":\"80 g\",\"Total Sugars\":\"43 g\",\"Total Fat\":\"1.0 g\",\"Dietary Fiber\":\"8.3 g\",\"Sodium\":\"4 mg\"}', '0.030', 'Best before 6 months from the date of packaging.', 'Store in cool and dry place.', 'assets/images/products/prod_69d5f40fe7a45.jpeg', '', 80.00, 120.00, 0, 12, NULL, 1, 0, 0, 0, 1, 'India', '2026-02-11 15:48:12', '2026-04-08 06:22:07'),
(22, 1, 'Apple', 'apple', 'Driyum Apple is made from carefully selected apples, gently dehydrated to preserve their natural sweetness and crisp fruit character. Lightly chewy, subtly sweet, and refreshing—just real apple, with nothing added.', '[\"Apple\"]', '{\"Per 100 g\":\"\",\"Energy\":\"250 kcal\",\"Protein\":\"1.5 g\",\"Carbohydrate\":\"67 g\",\"Total Sugars\":\"58 g\",\"Total Fat\":\"0.5 g\",\"Dietary Fiber\":\"8.2 g\",\"Sodium\":\"4 mg\"}', '0.015', 'Best before 6 months from the date of packaging.', 'Store in cool and dry place.', 'assets/images/products/prod_69d5f3ade58a5.jpeg', '', 69.00, 120.00, 0, 12, NULL, 1, 0, 0, 0, 1, 'India', '2026-02-11 15:48:12', '2026-04-08 06:20:29'),
(23, 1, 'Kiwi', 'kiwi', 'Driyum Kiwi is bright, tangy, and naturally refreshing. Dehydrated from ripe kiwis, it delivers a bold balance of sweet and tart with a soft chew that wakes up your palate. A fruit snack with real character—nothing added, nothing hidden.', '[\"Kiwi\"]', '{\"Per 100 g\":\"\",\"Energy\":\"320 kcal\",\"Protein\":\"3.1 g\",\"Carbohydrate\":\"75 g\",\"Total Sugars\":\"46 g\",\"Total Fat\":\"1.1 g\",\"Dietary Fiber\":\"14.5 g\",\"Sodium\":\"6 mg\"}', '0.025', 'Best before 6 months from the date of packaging.', 'Store in cool and dry place.', 'assets/images/products/prod_69d5f3811ecde.jpeg', '', 120.00, 160.00, 0, 12, NULL, 1, 0, 0, 0, 1, 'India', '2026-02-11 15:48:12', '2026-04-08 06:19:45'),
(25, 5, 'Alle hachi (200g)', 'alle-hachi', 'Alle hachi have a mild, subtle flavour that blends effortlessly into cooked dishes. Traditionally sun-dried, it softens on cooking and absorbs spices beautifully, making it ideal for light curries, rice-based meals, and slow-cooked dishes. Naturally light and fibre-rich, it adds balance without overpowering the dish.', '[\"Sun-dried Bottle Gourd\"]', '{\"Per 100 g\":\"\",\"Energy\":\"320 kcal\",\"Total Carbohydrate\":\"73 g\",\"Total Sugars\":\"32 g\",\"Dietary Fibre\":\"14 g\",\"Protein\":\"13 g\",\"Total Fat\":\"2.5 g\",\"Saturated Fat\":\"0.5 g\",\"Trans Fat\":\"0 g\",\"Sodium\":\"50 mg\"}', '0.200', 'Best before 6 months from the date of packaging.', 'Store in cool and dry place.', 'assets/images/products/prod_69d5f31b684c1.jpeg', '', 249.00, 349.00, 0, 5, NULL, 1, 1, 0, 0, 1, 'India', '2026-02-11 16:15:27', '2026-04-08 06:18:03'),
(26, 5, 'Wangan hachi ', 'wangan-hachi', 'Wangan hachi develop a deeper, earthy flavour when cooked. Sun-dried and rehydrated during cooking, it absorbs spices and gravies well, adding body and richness to curries and rice dishes. Naturally high in fibre, it is best enjoyed in slow-cooked or spice-forward preparations.', '[\"Sun-dried Eggplant (Brinjal)\"]', '{\"Per 100 g\":\"\",\"Energy\":\"310 kcal\",\"Total Carbohydrate\":\"68 g\",\"Total Sugars\":\"28 g\",\"Dietary Fibre\":\"22 g\",\"Protein\":\"14 g\",\"Total Fat\":\"2.5 g\",\"Saturated Fat\":\"0.6 g\",\"Trans Fat\":\"0 g\",\"Sodium\":\"30 mg\"}', '0.100', '6 months', 'Store in cool and dry place.', 'assets/images/products/prod_69d5f30831407.jpeg', '', 120.00, 200.00, 0, 2, NULL, 1, 1, 0, 0, 1, 'India', '2026-02-11 16:15:27', '2026-04-08 06:17:44'),
(27, 3, '3x KIWI', '3-pack-kiwi-slices', 'A trio of our premium tangy and refreshing dehydrated Kiwi slices. Perfect for stocking up on your favorite tart treat.', '[\"Kiwi\"]', '{\"Per 100 g\":\"\",\"Energy\":\"320 kcal\",\"Protein\":\"3.1 g\",\"Carbohydrate\":\"75 g\",\"Total Sugars\":\"46 g\",\"Total Fat\":\"1.1 g\",\"Dietary Fiber\":\"14.5 g\",\"Sodium\":\"6 mg\"}', '0.075', '6 months', 'Store in cool and dry place.', 'assets/images/products/prod_69d5f2a60d4dc.jpeg', '', 320.00, 480.00, 0, 12, NULL, 1, 1, 1, 0, 1, 'India', '2026-02-11 16:54:18', '2026-04-10 16:29:13'),
(28, 3, 'Hokh Suin Combo ', 'kashmiri-hokh-suin-combo-alle-wangan-', 'A traditional pairing of sun-dried Alle hachi [Bottle Gourd]200g ,Wangan hachi [Brinjal]100g and Ruwangan Hachi [ Tomato]150g . Perfect for authentic Kashmiri curries.', '[\"Sun-dried Bottle Gourd\",\"Sun-dried Brinjal\",\"Sun Dried Tomatoes\"]', '{\"Energy\":\"\",\"Protein\":\"\",\"Carbohydrates\":\"\",\"Total Sugars\":\"\",\"Total Fat\":\"\",\"Dietary Fiber\":\"\",\"Sodium\":\"\"}', '0.450', '6 months', 'Store in cool and dry place.', 'assets/images/products/prod_69d5f2ecf1713.jpeg', '', 550.00, 800.00, 0, 2, NULL, 1, 0, 0, 0, 1, 'India', '2026-02-11 16:54:18', '2026-04-08 06:17:16'),
(102, 1, 'Fig Rolls', 'fig-rolls', 'Driyum Fig rolls: These are naturally sweetened fig rolls with 80% fig and 20% jaggery, a great healthy alternative for candies.', '[\"Fig\",\"jaggery\",\"citric acid\"]', '{\"Energy\":\"\",\"Protein\":\"\",\"Carbohydrates\":\"\",\"Total Sugars\":\"\",\"Total Fat\":\"\",\"Dietary Fiber\":\"\",\"Sodium\":\"\"}', '0.250', NULL, NULL, 'assets/images/products/prod_69d5f68323b75.jpeg', '', 350.00, 0.00, 0, 5, NULL, 1, 0, 0, 0, 1, 'India', '2026-04-01 17:45:40', '2026-04-24 05:27:58');
